// The Store's tables on Postgres. PG_MIGRATIONS mirrors createStore's SQLite migrations (src/store.ts) one to one: the
// statement at each index makes the same change, so the two lists grow together, each new migration appended to both
// in the same commit. Translated as:
// - INTEGER PRIMARY KEY AUTOINCREMENT is BIGINT GENERATED BY DEFAULT AS IDENTITY, so a copy can insert its ids.
// - ms timestamps and counters are BIGINT; line and PR numbers stay INTEGER; the 0/1 flag is SMALLINT.
// - JSON stays TEXT: JSONB would reorder keys that the Store compares as strings.
// - target_key, and each text column in a primary key or index, is COLLATE "C", so it sorts by code point as in SQLite
//   whatever the database's collation, and tables join on target_key with one collation.
// plugin_updates (src/plugin-updates.ts) stays in SQLite, so it isn't here.
import { createHash } from "node:crypto";
import pg from "pg";
import type { Sql } from "./sql";

export const PG_MIGRATIONS: readonly string[] = [
  `CREATE TABLE IF NOT EXISTS reviews (
    target_key TEXT COLLATE "C" PRIMARY KEY, kind TEXT NOT NULL, number INTEGER, repo TEXT,
    title TEXT, author TEXT, base TEXT, head TEXT, git_ref TEXT, url TEXT,
    status TEXT NOT NULL, created_at BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS patches (target_key TEXT COLLATE "C" PRIMARY KEY, patch TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS guides (target_key TEXT COLLATE "C" PRIMARY KEY, guide TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS drafts (target_key TEXT COLLATE "C" PRIMARY KEY, verdict TEXT NOT NULL, body TEXT NOT NULL, comments TEXT NOT NULL)`,
  `ALTER TABLE reviews ADD COLUMN project_id TEXT`,
  `ALTER TABLE reviews ADD COLUMN head_sha TEXT`,
  `ALTER TABLE reviews ADD COLUMN cwd TEXT`,
  `CREATE TABLE IF NOT EXISTS file_views (
    target_key TEXT COLLATE "C" NOT NULL, file TEXT COLLATE "C" NOT NULL,
    hash TEXT NOT NULL, viewed_at BIGINT NOT NULL,
    PRIMARY KEY (target_key, file))`,
  `CREATE TABLE IF NOT EXISTS agent_threads (
    target_key TEXT COLLATE "C" PRIMARY KEY, thread_id TEXT NOT NULL, created_at BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS agent_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, target_key TEXT COLLATE "C" NOT NULL,
    role TEXT NOT NULL, text TEXT NOT NULL, context TEXT, created_at BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS generations (target_key TEXT COLLATE "C" PRIMARY KEY, generation_id TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS draft_comment_revisions (
    target_key TEXT COLLATE "C" NOT NULL, file TEXT COLLATE "C" NOT NULL, line INTEGER NOT NULL, side TEXT COLLATE "C" NOT NULL,
    patch_hash TEXT NOT NULL, PRIMARY KEY (target_key, file, line, side))`,
  `CREATE TABLE IF NOT EXISTS review_lifecycle (target_key TEXT COLLATE "C" PRIMARY KEY, state TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS review_preferences (id INTEGER PRIMARY KEY CHECK (id=1), value TEXT NOT NULL, revision BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS reviewer_notes (target_key TEXT COLLATE "C" PRIMARY KEY, body TEXT NOT NULL, revision BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS assistant_threads (target_key TEXT COLLATE "C" PRIMARY KEY, thread_id TEXT NOT NULL, created_at BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS review_context (target_key TEXT COLLATE "C" PRIMARY KEY, text TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS discussion_entries (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, target_key TEXT COLLATE "C" NOT NULL,
    file TEXT COLLATE "C" NOT NULL, line INTEGER NOT NULL, side TEXT COLLATE "C" NOT NULL,
    author TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL, start_line INTEGER, created_at BIGINT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS discussion_waits (
    target_key TEXT COLLATE "C" NOT NULL, file TEXT COLLATE "C" NOT NULL, line INTEGER NOT NULL, side TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY (target_key, file, line, side))`,
  `CREATE TABLE IF NOT EXISTS review_snapshots (
    target_key TEXT COLLATE "C" NOT NULL, head_sha TEXT COLLATE "C" NOT NULL, patch TEXT NOT NULL, created_at BIGINT NOT NULL,
    PRIMARY KEY (target_key, head_sha))`,
  `CREATE TABLE IF NOT EXISTS feedback_threads (
    target_key TEXT COLLATE "C" NOT NULL, thread_id TEXT COLLATE "C" NOT NULL, data TEXT NOT NULL, resolved_seen_at BIGINT,
    PRIMARY KEY (target_key, thread_id))`,
  `CREATE TABLE IF NOT EXISTS feedback_fetches (target_key TEXT COLLATE "C" PRIMARY KEY, fetched_at BIGINT NOT NULL, pr_updated_at BIGINT)`,
  `CREATE TABLE IF NOT EXISTS assessment_items (
    target_key TEXT COLLATE "C" NOT NULL, head_sha TEXT COLLATE "C" NOT NULL, item_id TEXT COLLATE "C" NOT NULL, data TEXT NOT NULL,
    PRIMARY KEY (target_key, head_sha, item_id))`,
  `CREATE TABLE IF NOT EXISTS assessment_runs (
    target_key TEXT COLLATE "C" NOT NULL, head_sha TEXT COLLATE "C" NOT NULL, data TEXT NOT NULL, assessed_at BIGINT NOT NULL,
    PRIMARY KEY (target_key, head_sha))`,
  `CREATE TABLE IF NOT EXISTS reply_drafts (
    target_key TEXT COLLATE "C" NOT NULL, thread_id TEXT COLLATE "C" NOT NULL, body TEXT NOT NULL, author TEXT NOT NULL, updated_at BIGINT NOT NULL,
    PRIMARY KEY (target_key, thread_id))`,
  `CREATE TABLE IF NOT EXISTS discovery_ignores (target_key TEXT COLLATE "C" PRIMARY KEY, ignored_at BIGINT NOT NULL)`,
  `ALTER TABLE draft_comment_revisions ADD COLUMN code TEXT`,
  `CREATE TABLE IF NOT EXISTS guide_backups (target_key TEXT COLLATE "C" PRIMARY KEY, data TEXT NOT NULL)`,
  `ALTER TABLE drafts ADD COLUMN meta TEXT`,
  `ALTER TABLE discussion_entries ADD COLUMN previous TEXT`,
  `ALTER TABLE generations ADD COLUMN worker_id TEXT`,
  `ALTER TABLE patches ADD COLUMN hash TEXT`,
  `ALTER TABLE draft_comment_revisions ADD COLUMN start_code TEXT`,
  `CREATE TABLE IF NOT EXISTS agent_comment_changes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, target_key TEXT COLLATE "C" NOT NULL, file TEXT NOT NULL, line INTEGER NOT NULL, side TEXT NOT NULL,
    kind TEXT NOT NULL, code TEXT, body TEXT NOT NULL, removed TEXT, at BIGINT NOT NULL, recorded SMALLINT NOT NULL DEFAULT 0)`,
  `CREATE TABLE IF NOT EXISTS agent_comment_outcomes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, repo TEXT NOT NULL, file TEXT NOT NULL, outcome TEXT NOT NULL, body TEXT NOT NULL, edited TEXT, at BIGINT NOT NULL)`,
  `CREATE INDEX IF NOT EXISTS discussion_entries_location ON discussion_entries (target_key, file, line, side)`,
  `ALTER TABLE review_preferences ADD COLUMN knobs TEXT`,
  `ALTER TABLE agent_comment_changes ADD COLUMN reason TEXT`,
  `CREATE TABLE IF NOT EXISTS filter_views (id TEXT COLLATE "C" PRIMARY KEY, name TEXT NOT NULL, filters TEXT NOT NULL, created_at BIGINT NOT NULL)`,
];

const statementHash = (statement: string) => createHash("sha256").update(statement).digest("hex");

/** Whether migratePg has made `schema`'s tables: for the plugin, only bb review storage migrate does. */
export async function pgSchemaMigrated(sql: Sql, schema: string): Promise<boolean> {
  return (await sql.get<{ found: string | null }>(`SELECT to_regclass(?) AS found`, [`${pg.escapeIdentifier(schema)}.crw_migrations`]))?.found != null;
}

/**
 * Create `schema` if it's missing and apply the statements its crw_migrations doesn't record, all in one transaction
 * under an advisory lock, so instances starting together apply each statement once. As with bb.storage.migrate, a
 * statement's index is its id, and a shipped statement whose text changed refuses to apply anything: append a new one.
 * Runs on a connection whose search_path is `schema`.
 */
export async function migratePg(sql: Sql, schema: string, statements: readonly string[] = PG_MIGRATIONS): Promise<void> {
  const hashes = statements.map(statementHash);
  await sql.transaction(async () => {
    await sql.get(`SELECT pg_advisory_xact_lock(hashtext(?))`, [`code-review-workspace:migrations:${schema}`]);
    // Checked first: CREATE SCHEMA IF NOT EXISTS needs the database's CREATE privilege even when the schema is there.
    if (!await sql.get(`SELECT 1 FROM pg_namespace WHERE nspname=?`, [schema])) await sql.run(`CREATE SCHEMA ${pg.escapeIdentifier(schema)}`);
    await sql.run(`CREATE TABLE IF NOT EXISTS crw_migrations (id INTEGER PRIMARY KEY, statement_hash TEXT NOT NULL, applied_at BIGINT NOT NULL)`);
    const applied = new Map((await sql.all<{ id: number; statement_hash: string }>(`SELECT id, statement_hash FROM crw_migrations ORDER BY id`))
      .map((row) => [row.id, row.statement_hash]));
    hashes.forEach((hash, id) => {
      const recorded = applied.get(id);
      if (recorded !== undefined && recorded !== hash) {
        throw new Error(`Postgres migration ${id} does not match the statement it recorded; append a new migration instead of changing or reusing an index`);
      }
    });
    for (const [id, statement] of statements.entries()) {
      if (applied.has(id)) continue;
      await sql.run(statement);
      await sql.run(`INSERT INTO crw_migrations (id, statement_hash, applied_at) VALUES (?, ?, ?)`, [id, hashes[id]!, Date.now()]);
    }
  });
}
